function uiFitWords(text,max){text=String(text||'').trim();const words=text.split(/\s+/);if(words.length<=max)return text;const cut=words.slice(0,max).join(' ');const at=Math.max(cut.lastIndexOf('. '),cut.lastIndexOf('.\n'),cut.lastIndexOf(', '));return (at>cut.length*.6?cut.slice(0,at+1):cut).replace(/[,;:\s]+$/,'')}
