  synopsis:uiFitWords(j(b.logline||c.logline,b.premise||c.premise,b.longTermGoal&&'Long-term goal: '+b.longTermGoal,b.longTermDevelopment&&'Direction:\n'+b.longTermDevelopment),4000),
  characters:chars.map(x=>x.name+'\n'+x.text).join('\n\n'),characterList:chars,
  worldList:[{name:'World & Rules',text:j(b.world,b.worldRules&&'Rules: '+b.worldRules,b.timeline&&'Timeline: '+b.timeline)},...(sd.glossary||[]).filter(g=>!/nhân vật|character/i.test(g.kind||'')&&!chars.some(c=>String(c.name).trim().toLowerCase()===String(g.term).trim().toLowerCase())).slice(0,15).map(g=>({name:g.term,text:g.note||''}))].filter(x=>x.name&&(x.text||x.name!=='World & Rules')),
