  worldbuilding:j(b.world,b.worldRules&&'Rules: '+b.worldRules,b.timeline&&'Timeline: '+b.timeline,(sd.glossary||[]).length&&'Names and terms (keep spelling):\n'+sd.glossary.map(g=>'- '+g.term+(g.note?': '+g.note:'')).join('\n')),
