// ---- ChatGPT takes over when Sudowrite is out of credits (on by default; Settings → Sudowrite Adapter).
// "Out of credits" is known only from Sudowrite itself (a stopped job with out_of_credits, or a live credit check = 0);
// it is cleared when a live check shows credits again or you press "Đã nạp credit".
function uiSudoFallbackOn(){return db.uiSettings?.sudoFallback!==false}
