const UI_SB_VERIFY={braindump:'live',genre:'live',synopsis:'live',characters:'live',worldbuilding:'live',outline:'live',style:'hand'};
const UI_SB_FIELD={braindump:'Braindump',genre:'Genre',style:'Style',synopsis:'Synopsis',characters:'Characters',worldbuilding:'Worldbuilding',outline:'Outline'};
const UI_SB_TRAITS=[['personality','Tính cách','Personality'],['motivations','Mục tiêu & động lực','Motivations'],['conflict','Mâu thuẫn / bí mật','Internal Conflict'],['strengths','Điểm mạnh','Strengths'],['weaknesses','Điểm yếu','Weaknesses'],['arc','Hành trình','Character Arc'],['physical','Ngoại hình','Physical Description']];
