async function uiSbFetch(force){if(uiSbBusy||(!force&&uiState.sbSync&&Date.now()-uiState.sbSync.at<60000))return;uiSbBusy=true;try{const r=await xpCall('XP_SUDO_LAST_REPORT',{},4000);uiState.sbSync={at:Date.now(),ok:!!r?.ok,report:r?.report||null,health:r?.health||null,mgr:r?.mgr||null,version:r?.version||'',error:r?.ok?'':(r?.error||'Adapter không trả lời')};if(r?.ok&&r.health?.ok&&r.health.credits!=null)uiSudoMarkCredits(r.health.credits)}catch(e){uiState.sbSync={at:Date.now(),ok:false,error:e.message||'Chưa thấy Sudowrite Adapter'}}finally{uiSbBusy=false}uiChipsRefresh();const ae=typeof document!=='undefined'&&document.activeElement;if(typeof document!=='undefined'&&document.querySelector('.sb-side')&&!(ae&&/INPUT|TEXTAREA|SELECT/.test(ae.tagName)))uiRender()}
if(typeof window!=='undefined'&&typeof setInterval==='function'){setTimeout(()=>uiSbFetch(true),2500);setInterval(()=>uiSbFetch(true),60000)}
