 if(key==='worldbuilding'||key==='outline'){const list=(key==='outline'?k.outlineList:k.worldList)||[];if(!list.length)return '<p class="st-empty">Chưa có dữ liệu cho '+lab+'.</p>';return list.map(x=>'<div class="sb-card"><header><b>'+esc(x.name)+'</b></header><p class="sb-text">'+esc(String(x.text||'').slice(0,1200))+'</p></div>').join('')}
