function uiStoryProduce(s,stage,j){if(!s)return `<div class="st-body"><section class="st-panel"><p class="st-empty">Tạo truyện ở bước 1, rồi duyệt cốt truyện và dàn ý ở bước 2 trước khi sản xuất chương.</p></section></div>`;return `<div class="st-body sp-body">${uiChapterCol(s)}${uiChapterEditor(s)}${uiStoryAssistant(s,stage,j,uiProduceTask(s))}</div>`}
function uiChapterSave(id){const c=db.content.find(x=>x.id===id),d=(uiState.chDraft||{})[id];if(!c||!d)return false;if(['approved','live'].includes(c.status))throw Error('Chương đã duyệt đang khóa. Tạo Revision để sửa.');const s=db.series.find(x=>x.id===c.seriesId),n=Number(c.chapterNumber),t=String(d.title??'').trim(),title=t&&t!==uiChTitle(s,c)?'Chương '+n+' — '+t:c.title,body=d.body??c.body??'';delete uiState.chDraft[id];if(title===c.title&&body===(c.body||''))return false;const now=new Date().toISOString();uiPersist(()=>{c.history=[...(Array.isArray(c.history)?c.history:[]),{at:now,title:c.title,body:c.body,status:c.status}].slice(-30);c.title=title;if(body!==(c.body||'')){c.body=body;c.bodyRevision=Number(c.bodyRevision||1)+1}c.updatedAt=now});return true}
