if(missing.length){await lfSend(s,'GENERATE_OUTLINE',{extendTo:end,preserveExisting:true});toast('Dàn ý chưa có kế hoạch cho Chương '+missing[0]+(missing.length>1?'–'+missing.at(-1):'')+'. Đã nhờ ChatGPT mở rộng dàn ý; duyệt ở bước 2 rồi bấm Sản xuất lại.');return}
