async function uiBatchStep(s){const b=s.uiBatch;if(!b||b.status!=='running')return;uiState.batchSending??={};if(uiState.batchSending[s.id])return;uiState.batchSending[s.id]=true;try{const c=lfChapters(s).filter(x=>Number(x.chapterNumber)===b.current).at(-1);if(c&&String(c.body||'').trim()&&!uiChBusy(uiChJob(c))&&uiChJob(c)?.status!=='error')return uiBatchAdvance(s);await uiChapterWrite(s,c||null,'new',b)}catch(e){uiPersist(()=>{b.status='error';b.error=e.message});throw e}finally{delete uiState.batchSending[s.id]}}
