function uiStoryReview(s){if(!s)return `<div class="st-body"><section class="st-panel"><p class="st-empty">Tạo truyện và sản xuất chương trước khi đánh giá.</p></section></div>`;return `<div class="st-body sp-body rv-body">${uiChapterCol(s,'review')}${uiChapterReviewPanel(s)}${uiQaPanel(s)}</div>`}
let uiBatchBusy=false;
async function uiBatchTick(){if(uiBatchBusy)return;uiBatchBusy=true;let changed=false;try{for(const s of db.series){const b=s.uiBatch;if(!b||b.status!=='running')continue;const c=lfChapters(s).filter(x=>Number(x.chapterNumber)===b.current).at(-1),j=uiChJob(c);if((!c||!j||j.batchId!==b.id)&&!(uiState.batchSending||{})[s.id]){if(c&&String(c.body||'').trim()&&!uiChBusy(j)&&j?.status!=='ready'){changed=true;try{await uiBatchAdvance(s)}catch(e){toast(e.message)}continue}changed=true;try{await uiBatchStep(s)}catch(e){toast(e.message)}continue}if(!c||!j||j.batchId!==b.id)continue;if(j.status==='applied'){changed=true;if(!(uiState.chDraft||{})[(uiState.chOpen||{})[s.id]])(uiState.chOpen??={})[s.id]=c.id;try{await uiBatchAdvance(s)}catch(e){toast(e.message)}}else if(j.status==='error'){changed=true;uiPersist(()=>{b.status='error';b.error=j.error||'ChatGPT báo lỗi'})}else if(j.status==='stopped'){changed=true;uiPersist(()=>b.status='paused')}}}finally{uiBatchBusy=false}if(changed&&typeof view!=='undefined'&&view==='series')uiRender()}
