function uiPrintIcon(name){return `<svg class="pr-ico" viewBox="0 0 24 24" aria-hidden="true"><path d="${({shirt:'M8.5 3.5L3 6.5l2 4 2.5-1V20h9V9.5l2.5 1 2-4-5.5-3c-.6 1.6-2 2.5-3.5 2.5s-2.9-.9-3.5-2.5z',image:'M4 4h16v16H4z M4 16l5-5 4 4 3-3 4 4 M15 8.5h.01',doc:'M6 3h9l4 4v14H6z M14 3v5h5 M9 13h7 M9 17h5',box:'M3 7l9-4 9 4v10l-9 4-9-4z M3 7l9 4 9-4 M12 11v10',tag:'M3 12V4h8l10 10-8 8z M7.5 7.5h.01',price:'M20.5 12.5l-8 8-9-9V3.5h8z M7.5 7.5h.01',clock:'M12 7v5l3 2 M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18',chevron:'M9 6l6 6-6 6',arrow:'M5 12h14 M13 6l6 6-6 6',check:'M5 12.5l4.5 4.5L19 7.5',plus:'M12 5v14 M5 12h14',info:'M12 11v6 M12 7.5v.5 M12 2.5a9.5 9.5 0 1 0 0 19 9.5 9.5 0 0 0 0-19',link:'M10 14a4 4 0 0 0 6 0l3-3a4 4 0 0 0-6-6l-1 1 M14 10a4 4 0 0 0-6 0l-3 3a4 4 0 0 0 6 6l1-1'})[name]}"/></svg>`}
function uiPrintTypeIcon(t){return t==='Áo thun'?'shirt':t==='Poster'?'image':t==='Sản phẩm số'?'doc':'box'}
function uiPrintStats(p){const assets=(db.assets||[]).filter(a=>a.printProjectId===p.id),created=assets.filter(a=>a.data),approved=created.filter(a=>a.approval==='approved'),count=Number(p.count)||12;return{assets,created,approved,count}}
function uiPrintStatus(p){const s=uiPrintStats(p);if(!s.assets.length)return(p.references||[]).length||p.keyword?'Đang chuẩn bị':'Chưa triển khai';if(s.created.length<s.count)return `${s.created.length}/${s.count} thiết kế · Đang sản xuất`;if(s.approved.length<s.created.length)return 'Chờ duyệt thiết kế';return `${s.count} thiết kế · Đã duyệt`}
function uiPrintLibrary(){const list=db.printProjects||[],pg=uiPage(list,uiState.pages.prints,6),creating=uiState.creatingPrint||!list.length,legacy=uiLegacyItems().length;return `<div class="pr-library"><h2>Bộ sản phẩm của tôi</h2><button class="pr-new" data-ui-action="new-print">${uiPrintIcon('plus')}Tạo bộ sản phẩm</button><div class="pr-items">${creating?`<button class="pr-item active" data-ui-action="new-print"><span class="pr-item-icon">${uiPrintIcon(uiPrintTypeIcon(uiPrintNewDraft().productType||'Áo thun'))}</span><span><strong>${esc(String(uiPrintNewDraft().keyword||'').trim().slice(0,40)||'Bộ sản phẩm mới')}</strong><small>Đang nhập định hướng</small></span></button>`:''}${pg.items.map(p=>`<button class="pr-item ${!creating&&uiState.print===p.id?'active':''}" data-ui-select="${p.id}" data-project-type="print"><span class="pr-item-icon">${uiPrintIcon(uiPrintTypeIcon(p.productType))}</span><span><strong>${esc(p.title)}</strong><small>${esc(uiPrintStatus(p))}</small></span></button>`).join('')}</div>${uiPager('prints',list,6)}${legacy?`<button class="pr-link pr-legacy" data-ui-action="legacy-assets">Ảnh / sản phẩm hiện có (${legacy})</button>`:''}<div class="pr-library-foot">${uiPrintIcon('info')}Chọn bộ sản phẩm để sản xuất tiếp</div></div>`}
function uiPrintSteps(step){return `<div class="pr-steps">${['Tìm ý tưởng','Tạo thiết kế','Chuẩn bị đăng Etsy'].map((label,i)=>`${i?'<i></i>':''}<span class="${i+1===step?'active':i+1<step?'done':''}"><b>${i+1<step?uiPrintIcon('check'):i+1}</b>${i+1}. ${label}</span>`).join('')}</div>`}
function uiPrintSource(p,isNew){const f=isNew?'data-ui-newprint-field':'data-ui-print-field',sf=isNew?'data-ui-newprint-source':'data-ui-print-source',sources=p.sources||uiPrintSources,count=Number(p.count)||12,counts=[...new Set([4,6,8,10,12,16,20,24,30,40,50,count])].sort((a,b)=>a-b);return `<section class="pr-section pr-source"><h3>Nguồn tham khảo & định hướng</h3><div class="pr-source-grid"><div class="pr-col"><label for="uPrintKeyword">Chủ đề / từ khóa</label><input id="uPrintKeyword" ${f}="keyword" value="${esc(p.keyword||'')}" placeholder="Ví dụ: Áo chữ tối giản cho người yêu đọc sách"><p class="pr-label">Nguồn tham khảo</p><div class="pr-checks">${uiPrintSources.map(n=>`<label><input type="checkbox" ${sf}="${n}" ${sources.includes(n)?'checked':''}>${n}</label>`).join('')}</div><div class="pr-row"><button class="pr-outline" data-ui-action="find-references">Tìm sản phẩm tham khảo</button><span class="pr-pill">Chờ tích hợp</span></div><small class="pr-hint">Có thể dán link hoặc thêm ảnh tham khảo thủ công</small></div><div class="pr-col"><label for="uPrintStyle">Phong cách thiết kế</label><textarea id="uPrintStyle" ${f}="style" placeholder="Màu sắc, kiểu chữ, bố cục, phong cách…">${esc(p.style||'')}</textarea><div class="pr-three"><label>Sản phẩm<select ${f}="productType">${uiPrintProducts.map(v=>`<option ${v===(p.productType||'Áo thun')?'selected':''}>${v}</option>`).join('')}</select></label><label>Số thiết kế<select ${f}="count">${counts.map(v=>`<option value="${v}" ${v===count?'selected':''}>${v}</option>`).join('')}</select></label><label>Đầu ra<select ${f}="output">${uiPrintOutputs.map(v=>`<option ${v===(p.output||'PNG nền trong')?'selected':''}>${v}</option>`).join('')}</select></label></div></div></div>${isNew?`<div class="pr-create"><button class="primary pr-primary" data-ui-action="create-print">Tạo bộ sản phẩm từ định hướng này</button>${uiState.creatingPrint&&(db.printProjects||[]).length?'<button class="pr-link" data-ui-action="cancel-new-print">Hủy</button>':''}<small>Nhập chủ đề, chọn sản phẩm rồi tạo để thêm mẫu tham khảo và thiết kế.</small></div>`:''}</section>`}
function uiPrintRefSource(r){const s=String(r.source||'');return /pinterest/i.test(s)?'Pinterest':/google/i.test(s)?'Google':/etsy/i.test(s)?'Etsy':s||'Tham khảo'}
function uiPrintRefs(p){const refs=p?(p.references||[]):[],pg=uiPage(refs,uiState.pages.references,4),dis=p?'':'disabled';const cards=pg.items.map(r=>`<figure class="pr-ref ${r.selected?'selected':''}"><button class="pr-ref-thumb" data-ui-reference="${r.id}" aria-label="Xem ${esc(r.title)}">${r.data?`<img src="${esc(r.data)}" alt="${esc(r.title)}">`:`<span class="pr-placeholder">${uiPrintIcon('link')}<span>${esc(r.title||'Link tham khảo')}</span></span>`}</button><button class="pr-ref-check" data-ui-ref-select="${r.id}" aria-pressed="${!!r.selected}" aria-label="${r.selected?'Bỏ chọn':'Chọn'} mẫu ${esc(r.title)}">${r.selected?uiPrintIcon('check'):''}</button><figcaption>${esc(r.link||r.data?uiPrintRefSource(r)+' · Tham khảo':'Ý tưởng mới')}</figcaption></figure>`).join('');const fill=Array.from({length:Math.max(0,4-pg.items.length)},(_,i)=>`<figure class="pr-ref empty"><button class="pr-ref-thumb" data-ui-action="add-reference" ${dis}><span class="pr-placeholder">${uiPrintIcon('image')}<span>${p?'Thêm mẫu tham khảo':'Mẫu tham khảo'}</span></span></button><figcaption>${i===0&&!refs.length?'Pinterest / Google / Etsy':'Ảnh / link của bạn'}</figcaption></figure>`).join('');return `<section class="pr-section pr-refs ${p?'':'pr-disabled'}"><div class="pr-head"><h3>Ý tưởng & mẫu tham khảo</h3><span class="pr-spacer"></span>${uiPager('references',refs,4)}<button class="pr-link" data-ui-action="add-reference" ${dis}>${uiPrintIcon('plus')}Thêm ảnh / link</button></div><div class="pr-ref-grid">${cards}${fill}</div><small class="pr-hint">Tham khảo xu hướng để tạo thiết kế gốc; không sao chép mẫu.</small></section>`}
function uiPrintDesigns(p){const st=p?uiPrintStats(p):{assets:[],created:[],approved:[],count:Number(uiPrintNewDraft().count)||12},pg=uiPage(st.assets,uiState.pages.designs,3),dis=p?'':'disabled',batch=Math.min(30,Math.max(1,Number(uiState.printDrafts[p?.id]?.batchCount)||6)),offset=pg.page*3;const cards=pg.items.map((a,i)=>{const tone=!a.data?'muted':a.approval==='approved'?'green':'amber';return `<figure class="pr-design"><button class="pr-design-thumb" data-workflow="asset" data-wid="${a.id}" aria-label="Mở ${esc(a.title)}">${a.data?`<img src="${a.data}" alt="${esc(a.title)}">`:`<span class="pr-placeholder">${uiPrintIcon('image')}<span>Chưa có ảnh</span></span>`}</button><figcaption><span>Mẫu ${String(offset+i+1).padStart(2,'0')}</span><span class="pr-status ${tone}"><i></i>${!a.data?'Chưa có ảnh':a.approval==='approved'?'Đã duyệt':'Chờ duyệt'}</span></figcaption></figure>`}).join('');const fill=Array.from({length:Math.max(0,3-pg.items.length)},(_,i)=>`<figure class="pr-design empty"><button class="pr-design-thumb" data-ui-action="design-batch" ${dis}><span class="pr-placeholder">${uiPrintIcon('image')}<span>Chưa có thiết kế</span></span></button><figcaption><span>Mẫu ${String(offset+pg.items.length+i+1).padStart(2,'0')}</span><span class="pr-status muted"><i></i>Chưa tạo</span></figcaption></figure>`).join('');return `<section class="pr-section pr-designs ${p?'':'pr-disabled'}"><div class="pr-head"><h3>Thiết kế đang sản xuất</h3><span class="pr-spacer"></span><small>${st.created.length}/${st.count} thiết kế đã tạo · ${st.approved.length} thiết kế đã duyệt</small></div><div class="pr-design-grid">${cards}${fill}</div><div class="pr-batch"><button class="primary pr-primary" data-ui-action="design-batch" ${dis}>Tạo đợt thiết kế</button><label for="uDesignBatch">Số lượng:</label><input id="uDesignBatch" type="number" min="1" max="30" value="${batch}" ${dis}><small>Thiết kế mới luôn chờ bạn duyệt</small><span class="pr-spacer"></span>${uiPager('designs',st.assets,3)}<button class="pr-link" data-ui-action="upload-design" ${dis}>Nhập ảnh</button></div></section>`}
function uiPrintEtsy(p){const st=p?uiPrintStats(p):{approved:[]},w=p?db.workflows.find(w=>w.id===p.etsyWorkflowId):null,dis=p?'':'disabled',rows=[['image','Ảnh sản phẩm',st.approved.length?st.approved.length+' ảnh đã duyệt':'Chưa có ảnh duyệt',st.approved.length?'green':'muted'],['image','Tiêu đề & mô tả',w?.description?'Bản nháp':'Chưa tạo',w?.description?'blue':'amber'],['tag','13 thẻ tag',w?.tags?String(w.tags).split(',').filter(x=>x.trim()).length+' tag':'Chưa tạo',w?.tags?'green':'amber'],['price','Giá & loại sản phẩm',w?.price?'Đã thiết lập':'Chưa thiết lập',w?.price?'green':'red']];return `<section class="pr-section pr-etsy ${p?'':'pr-disabled'}"><h3>Chuẩn bị sản phẩm Etsy</h3><div class="pr-checklist">${rows.map(([ico,label,status,tone])=>`<button class="pr-check-row" data-ui-action="etsy-draft" ${dis}>${uiPrintIcon(ico)}<span>${label}</span><span class="pr-badge ${tone}">${esc(status)}</span>${uiPrintIcon('chevron')}</button>`).join('')}</div><button class="pr-outline pr-wide" data-ui-action="etsy-draft" ${dis}>Mở bản nháp sản phẩm</button><div class="pr-auto">${uiPrintIcon('clock')}<span>Tự động đăng / hẹn giờ: Chưa tích hợp</span><button class="pr-link" data-ui-printtab="publish">Xem kết nối đăng bán ${uiPrintIcon('arrow')}</button></div></section>`}
function uiPrintPanel(project){const p=project?{...project,...uiState.printDrafts[project.id]}:null,src=p||uiPrintNewDraft(),st=p?uiPrintStats(p):null,step=!p||!(p.keyword||(p.references||[]).length)?1:p.etsyWorkflowId?3:2;return `<section class="pr-panel"><div class="pr-title"><h2>${esc(p?p.title:'Bộ sản phẩm mới')}</h2><span class="pr-badge ${p?'green':'muted'}">${p?'Đang chuẩn bị':'Chưa triển khai'}</span><span class="pr-spacer"></span><span class="pr-badge gray">Tự động hóa: Chờ tích hợp</span></div>${uiPrintSteps(step)}${uiPrintSource(src,!p)}${uiPrintRefs(p)}<div class="pr-bottom">${uiPrintDesigns(p)}${uiPrintEtsy(p)}</div></section>`}
function uiPrint(){const list=db.printProjects||[];if(uiState.creatingPrint&&!list.length)uiState.creatingPrint=false;if(!uiState.creatingPrint&&!list.some(p=>p.id===uiState.print)){let saved='';try{saved=localStorage.getItem('xuong-print-selected')||''}catch{}uiState.print=list.some(p=>p.id===saved)?saved:list[0]?.id||''}const p=uiState.creatingPrint?null:list.find(p=>p.id===uiState.print);try{if(p)localStorage.setItem('xuong-print-selected',p.id)}catch{}return `<div class="pr-workspace">${uiPrintLibrary()}<div class="pr-studio"><div class="pr-tabs" role="tablist"><button role="tab" aria-selected="${uiState.printTab!=='publish'}" data-ui-printtab="produce" class="${uiState.printTab!=='publish'?'active':''}">Sản xuất thiết kế</button><button role="tab" aria-selected="${uiState.printTab==='publish'}" data-ui-printtab="publish" class="${uiState.printTab==='publish'?'active':''}">Kết nối đăng bán</button></div>${uiState.printTab==='publish'?uiPublishing('print',p):uiPrintPanel(p)}</div></div>`}
async function uiNewPrint(){uiFlushPrint();if(!uiState.creatingPrint)uiState.prevPrint=uiState.print;uiState.creatingPrint=true;uiState.print='';uiState.printTab='produce';view='prints';if(location.hash!=='#prints')location.hash='prints';uiRender();setTimeout(()=>$('#uPrintKeyword')?.focus(),0)}
async function uiCreatePrint(){const d=uiPrintNewDraft(),keyword=String(d.keyword||'').trim();if(!keyword){$('#uPrintKeyword')?.focus();throw Error('Nhập chủ đề / từ khóa trước.')}const count=Number(d.count)||12;if(!Number.isInteger(count)||count<1||count>100)throw Error('Số thiết kế từ 1 đến 100.');const p={id:uid(),title:uiWorkingTitle(keyword),keyword,productType:uiPrintProducts.includes(d.productType)?d.productType:'Áo thun',style:String(d.style||''),count,output:uiPrintOutputs.includes(d.output)?d.output:'PNG nền trong',sources:Array.isArray(d.sources)?d.sources.filter(x=>uiPrintSources.includes(x)):[...uiPrintSources],references:[]};uiPersist(()=>{db.printProjects??=[];db.printProjects.push(p)});uiState.print=p.id;uiState.creatingPrint=false;uiState.newPrint={};uiPrintKeepDraft();uiState.pages.prints=Math.floor((db.printProjects.length-1)/6);toast('Đã tạo bộ sản phẩm. Thêm mẫu tham khảo hoặc tạo đợt thiết kế.')}
async function uiFindReferences(p){const src=p?{...p,...uiState.printDrafts[p.id]}:uiPrintNewDraft(),q=String(src.keyword||'').trim(),sources=src.sources||uiPrintSources;if(!q){$('#uPrintKeyword')?.focus();throw Error('Nhập chủ đề / từ khóa để tìm tham khảo.')}if(!sources.length)throw Error('Chọn ít nhất một nguồn tham khảo.');const url={Pinterest:'https://www.pinterest.com/search/pins/?q=',Google:'https://www.google.com/search?tbm=isch&q=',Etsy:'https://www.etsy.com/search?q='};await uiReadDocument(`<p>Tự động lấy sản phẩm từ Pinterest / Google / Etsy chưa được tích hợp. Mở trang tìm kiếm bên dưới, chọn mẫu phù hợp rồi bấm <b>＋ Thêm ảnh / link</b> để lưu vào bộ sản phẩm.</p>${sources.map(n=>`<p>${safeLink(url[n]+encodeURIComponent(q),'Tìm “'+q+'” trên '+n)}</p>`).join('')}<p>Chỉ dùng để tham khảo xu hướng; thiết kế phải là bản gốc.</p>`,'Tìm sản phẩm tham khảo')}
function uiBridgeDetails(){const state=bridgeConnectionState(),present=!!bridgeStatus.ok,connected=present&&bridgeStatus.connected,last=(db.aiJobs||[]).filter(j=>j.resultText&&['ready','applied'].includes(j.status)).at(-1);return `<div class="u-card-head"><span class="u-kpi-icon">${uiIcon('plug')}</span><div><h2>ChatGPT Bridge</h2><p>Sản xuất nội dung và hình ảnh qua ChatGPT Plus.</p></div><span class="u-spacer"></span>${uiBadge(state.label.replace(' — không nhận được Bridge',''),state.tone==='connected'?'green':state.tone==='checking'?'amber':'red')}</div><div class="u-diagnostic">${[['Extension trên trình duyệt',present?'Đã nhận Bridge':'Chưa nhận được Bridge',present?'green':'red',present?'Bridge '+esc(bridgeStatus.version||'')+' phản hồi.':'Chưa phát hiện extension trong trang này.'],['Tab ChatGPT',connected?'Đã chọn tab':'Chưa xác nhận',connected?'green':'muted',connected?esc(bridgeStatus.conversation?.title||'ChatGPT'):'Chưa xác nhận đã chọn tab ChatGPT.'],['Gửi / nhận kết quả',last?'Đã nhận kết quả':'Chưa kiểm tra',last?'green':'muted',last?'Có kết quả được lưu trong Xưởng.':'Chưa kiểm tra khả năng gửi / nhận kết quả.']].map(([label,status,tone,help])=>`<div><strong>${label}</strong>${uiBadge(status,tone)}<small>${help}</small></div>`).join('')}</div><small>Phiên bản hỗ trợ: 0.4.8 &nbsp; | &nbsp; Không dùng API key</small>`}
// Top-bar status: ChatGPT Bridge and Sudowrite Adapter. A chip opens the settings popup.
function uiMgrInfo(){const m=uiState.sbSync?.mgr;if(!uiState.sbSync)return ['wait','Đang kiểm tra'];if(!uiState.sbSync.ok||!m)return ['wait','Chưa rõ'];return ({running:['ok','Đang chạy lệnh'],connected:['ok','Đã kết nối'],idle:['ok','Đã kết nối'],unpaired:['bad','Chưa ghép đôi'],disconnected:['bad','Mất kết nối'],error:['bad','Lỗi']})[m.state]||(m.state?['ok','Đã kết nối']:['bad','Chưa ghép đôi'])}
function uiSudoInfo(){const sy=uiState.sbSync,h=sy?.health;if(!sy)return ['wait','Đang kiểm tra',''];if(!sy.ok)return ['wait','Chưa rõ','Sudowrite Adapter chưa trả lời'];if(typeof uiSudoCreditsOut==='function'&&uiSudoCreditsOut())return ['warn','Hết credit',uiSudoFallbackOn()?'ChatGPT đang viết thay Sudowrite':'Việc Sudowrite dừng chờ bạn'];if(!h||!h.ok||!h.inProject)return ['bad','Chưa mở dự án','Mở dự án Sudowrite trong một tab'];if(h.credits===0)return ['warn','Hết credit',''];return ['ok',h.credits!=null?h.credits.toLocaleString('vi-VN')+' credit':'Đang mở','Dự án '+String(h.url||'').replace(/^\/app\/project\//,'')]}
function uiStatusChips(){const chip=(cls,name,small,title,action)=>'<button class="u-chip '+cls+'" data-ui-action="'+(action||'settings')+'" title="'+esc(title||'')+'"><i></i>'+name+'<small>'+esc(small)+'</small></button>',ad0=typeof xpVersion==='string'&&xpVersion,old=ad0&&typeof uiVerLt==='function'&&uiVerLt(xpVersion,'0.7.5'),sw=uiSudoInfo(),mg=uiMgrInfo();
 return uiStatusChipsBase()+chip(sw[0],'Sudowrite',sw[1],sw[2])+chip(mg[0],'AI Manager',mg[1],uiState.sbSync?.mgr?.error||'')}
function uiStatusChipsBase(){const b=typeof bridgeConnectionState==='function'?bridgeConnectionState():{tone:'',label:'ChatGPT'},ok=b.tone==='connected',ad=typeof xpVersion==='string'&&xpVersion;
 return '<button class="u-chip '+(ok?'ok':b.tone==='checking'?'wait':'bad')+'" data-ui-action="settings" title="'+esc(b.help||b.label)+'"><i></i>ChatGPT<small>'+esc(ok?'Đã kết nối':b.label.replace(/ChatGPT/,'').split('—')[0].trim()||'Chưa kết nối')+'</small></button>'+
 '<button class="u-chip '+(ad?'ok':'bad')+'" data-ui-action="settings" title="'+esc(ad?'Sudowrite Adapter '+ad+' đang chạy trên trình duyệt này':'Chưa thấy extension Sudowrite Adapter trên trình duyệt này')+'"><i></i>Adapter<small>'+esc(ad?'v'+ad:'Chưa cài')+'</small></button>'}
function uiChipsRefresh(){const el=typeof document!=='undefined'&&document.getElementById('uStatusChips');if(el)el.innerHTML=uiStatusChips()}
// Who writes a story's chapters: Xưởng (ChatGPT via Bridge) or Sudowrite (Adapter). Chosen when the story is created.
// Sudowrite stories: add an empty chapter (title from the plan); writing happens on Sudowrite.
function uiSudoAddChapter(s){const n=lfNextChapter(s),d=lfChapterDefaults(s),plan=lfPlans(s,n).find(p=>p.kind==='chapter'),now=new Date().toISOString(),c={id:uid(),...d,title:plan?.title?'Chương '+n+' — '+plan.title:d.title,createdAt:now,updatedAt:now,history:[]};uiPersist(()=>db.content.push(c));if(typeof toast==='function')toast('Đã thêm Chương '+n+'. Bấm Tự viết trên Sudowrite để Sudowrite viết.');return c}
function uiWriterOf(s){return s?.writer==='sudowrite'||s?.writer==='xuong'?s.writer:''}
