async function uiCoverGenerate(s){const l=s.webnovelListing;if(!l?.coverPrompt)throw Error('Soạn hồ sơ Webnovel trước để có mô tả ảnh bìa.');if(typeof xnManualMode==='function'&&xnManualMode())throw Error('Vẽ ảnh bìa cần ChatGPT Bridge (đang ở chế độ dán tay).');const check=await bridgeCall('XN_STATUS',{},4000).catch(()=>null);if(!check?.ok||!check.connected)throw Error('Chưa kết nối ChatGPT. Mở tab ChatGPT, bấm Kết nối trong popup Bridge rồi bấm lại.');const now=new Date().toISOString(),asset={id:uid(),seriesId:s.id,title:'Bìa — '+l.bookName,approval:'draft',data:'',ratio:'3:4',prompt:l.coverPrompt,createdAt:now},prompt=['Create exactly one standalone image: a professional web novel BOOK COVER.','Aspect ratio: 3:4 portrait (final size 600x800 pixels).','Title text, large and correctly spelled near the top: "'+l.bookName+'". No other text, no watermark, no border, no collage.',l.coverPrompt].join('\n\n'),job={id:'xn_'+uid().replaceAll('-',''),type:'image',targetId:asset.id,title:'Ảnh bìa — '+l.bookName,seriesId:s.id,coverFor:s.id,createdAt:now,baseUpdatedAt:'',baseBody:'',status:'queued',prompt};
 uiPersist(()=>{db.assets.push(asset);db.aiJobs??=[];db.aiJobs.push(job)});const r=await bridgeCall('XN_START',{job:{id:job.id,type:'image',prompt}}).catch(e=>({ok:false,error:e.message}));if(!r?.ok){uiPersist(()=>{job.status='error';job.error=r?.error||'Không gửi được yêu cầu'});throw Error(job.error)}uiPersist(()=>job.status='waiting_send');if(typeof refreshBridge==='function')refreshBridge();toast('Đã nhờ ChatGPT vẽ ảnh bìa. Ảnh sẽ tự về Xưởng.')}
