async function uiTools(){const d=await choose('Công cụ hiện có',select('tool','Chọn công cụ',[['channels','Kênh'],['prompts','Thư viện câu lệnh'],['content','Nội dung'],['metrics','Số liệu'],['asset','Hình ảnh']], 'channels'));if(!d)return;if(d.tool==='asset'){openWorkflow('asset');return}const type=d.tool;await uiReadDocument(`<div class="u-spread"><h3>Dữ liệu hiện có</h3><button data-new="${type}">＋ Thêm mới</button></div>`+(db[type]||[]).map(row=>`<article class="u-chapter-row"><strong>${esc(row.title||row.name||row.date||row.id)}</strong><button data-edit="${type}" data-id="${row.id}">Mở / sửa</button>${type==='prompts'?`<button data-preview="${row.id}">Dùng câu lệnh</button>`:''}</article>`).join(''),'Công cụ hiện có')}
function uiCompactPanels(route){if(innerHeight>850)return;if(route==='settings'){const grid=document.querySelector('.u-settings-grid'),left=grid.children[0],right=grid.children[1];uiState.compact??={};const selected=uiState.compact.settings||0,nav=document.createElement('div');nav.className='u-segment u-settings-pages';nav.innerHTML=['Kết nối công cụ','Dữ liệu & vận hành'].map((label,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="settings" data-panel-index="${i}">${label}</button>`).join('');grid.before(nav);left.children[0].hidden=selected!==0;left.children[1].hidden=selected!==1;right.children[0].hidden=selected!==0;right.children[1].hidden=selected!==1;right.children[2].hidden=selected!==1;grid.classList.add('u-compact-settings');return}if(route!=='prints')return;const panel=document.querySelector(route==='series'?'.u-book-panel':'.u-print-panel');if(!panel)return;const items=route==='series'?[...panel.querySelectorAll(':scope>.u-section')]:[...panel.children].filter(el=>el.matches('.u-section,.u-print-bottom')),labels=route==='series'?['Ý tưởng & nguồn','Cốt truyện & nhân vật','Đợt chương']:['Nguồn & phong cách','Mẫu tham khảo','Thiết kế & Etsy'];uiState.compact??={};const selected=Math.min(uiState.compact[route]||0,items.length-1),nav=document.createElement('div');nav.className='u-panel-pages u-segment';nav.innerHTML=items.map((el,i)=>`<button class="${i===selected?'selected':''}" data-ui-panel="${route}" data-panel-index="${i}">${labels[i]}</button>`).join('');panel.children[1].after(nav);panel.classList.add('u-compact-panel');items.forEach((el,i)=>{el.hidden=i!==selected;el.classList.add('u-panel-page')})}
function uiPersist(fn){const before=JSON.stringify(db);try{fn();if(!save())throw Error('Không lưu được thay đổi.')}catch(e){db=JSON.parse(before);throw e}}
function uiSelectedBook(){return db.series.find(s=>s.id===uiState.book)}
function uiSelectedPrint(){return db.printProjects.find(p=>p.id===uiState.print)}
function uiFlushBook(){const s=uiSelectedBook(),draft=uiState.drafts[s?.id];if(!s||!draft)return;const {chapterLength,...rest}=draft,len=Math.round(Number(chapterLength));if(chapterLength!==undefined&&len>=300&&len!==s.chapterLength)uiPersist(()=>s.chapterLength=len);const current=lfPipeline(s).source,next={...current,...rest};if(JSON.stringify(current)!==JSON.stringify(next))uiPersist(()=>lfSetSource(s,next));delete uiState.drafts[s.id]}
function uiFlushPrint(){const p=uiSelectedPrint(),draft=uiState.printDrafts[p?.id];if(p&&draft)uiPersist(()=>Object.assign(p,draft));delete uiState.printDrafts[p?.id]}
async function uiNewBook(pick){if(!pick){uiState.pickWriter=true;return uiRender()}uiState.pickWriter=false;uiState.newWriter=pick;uiFlushBook();if(!uiState.creating)uiState.prevBook=uiState.book;uiState.creating=true;uiState.book='';uiState.storyTab='produce';view='series';if(location.hash!=='#series')location.hash='series';uiRender();setTimeout(()=>$('#uStoryIdea')?.focus(),0)}
async function uiBuildStory(s){uiFlushBook();const [stage,,kind]=uiCurrentStage(s);if(stage==='ready'){if(!await uiConfirm('Tạo lại concept sẽ cần duyệt lại các phần phụ thuộc. Chương đã duyệt vẫn được giữ. Tiếp tục?'))return;return await lfSend(s,'GENERATE_CONCEPT')}const artifact=lfPipeline(s).artifacts[stage];if(artifact&&artifact.dependency===lfDependency(s,stage))return uiReviewStage(s,stage);if(stage==='dna'&&!lfPipeline(s).parts.length){await lfSend(s,'ANALYZE_REFERENCE_LINK');return}if(stage==='dna'){const next=lfNextDNA(s);if(next.complete){lfArtifact(s,'dna',next.value);save();return}await lfSend(s,kind,next.scope)}else await lfSend(s,kind)}
async function uiReviewStage(s,stage){const a=lfPipeline(s).artifacts[stage];if(!a)throw Error('Chưa có kết quả để duyệt.');const labels={reviewVi:'Bản tiếng Việt để duyệt',coreTheme:'Chủ đề cốt lõi',audience:'Độc giả',openingHook:'Hook mở đầu',characterIntroduction:'Cách giới thiệu nhân vật',characterArchetypes:'Kiểu nhân vật',relationships:'Quan hệ',mainConflict:'Xung đột chính',secondaryConflicts:'Xung đột phụ',escalation:'Leo thang',plotTwists:'Twist',pacing:'Nhịp truyện',sectionStructure:'Cấu trúc chương',transitions:'Chuyển cảnh',cliffhangers:'Cliffhanger',curiosity:'Gây tò mò',emotionalTone:'Cảm xúc chủ đạo',narrativeStyle:'Giọng kể',averageSectionLength:'Độ dài chương',retentionFormula:'Công thức giữ chân',ending:'Kết',sourceIdentifiers:'Tên / tình tiết gốc cần tránh',genre:'Thể loại',title:'Tên truyện',logline:'Logline',premise:'Cốt truyện tổng quan',mainThreads:'Twist & nút thắt',originalityNotes:'Điểm khác biệt',world:'Thế giới',worldRules:'Quy tắc thế giới'};const text=Object.entries(a.value).sort(([x],[y])=>(y==='reviewVi')-(x==='reviewVi')).map(([k,v])=>`<p><b>${esc(labels[k]||k)}</b></p><p>${esc(typeof v==='string'?v:JSON.stringify(v,null,2))}</p>`).join('');await uiReadDocument(text,stage==='bible'?'Cốt truyện tổng quan':stage==='characters'?'Nhân vật':'Kết quả để duyệt')}
async function uiReadDocument(html,title='Nội dung'){const pending=choose(title,`<div class="u-reader">${html}</div>`);const reader=$('#pickerFields .u-reader');let split=false;for(const child of [...reader.children])if(['PRE','P'].includes(child.tagName)&&child.textContent.length>800){const nodes=uiSplitText(child.textContent).map(part=>{const node=document.createElement(child.tagName);node.textContent=part;return node});child.replaceWith(...nodes);split=true}uiPaginateContainer(reader,split||reader.querySelector('pre')?1:4);await pending}
async function uiEditBible(s){const a=lfPipeline(s).artifacts.bible;if(!a){toast('Xây dựng cốt truyện trước để chỉnh sửa.');return}const d=await choose('Điều chỉnh cốt truyện',input('title','Tên truyện',a.value.title)+input('premise','Cốt truyện tổng quan',a.value.premise,'textarea')+input('mainThreads','Twist & nút thắt',a.value.mainThreads,'textarea'));if(!d)return;const value={...a.value,...d};if(['title','premise','mainThreads'].some(k=>d[k]!==a.value[k]))delete value.reviewVi;lfValidateOutput(s,'GENERATE_STORY_BIBLE',value);uiPersist(()=>lfArtifact(s,'bible',value))}
