async function uiBatch(s){uiFlushBook();if(!lfApproved(s,'outline'))throw Error('Duyệt cốt truyện, nhân vật và dàn ý trước khi viết chương.');const count=Number($('#uChapterCount').value);if(!Number.isInteger(count)||count<1||count>30)throw Error('Mỗi đợt từ 1 đến 30 chương.');const next=lfNextChapter(s);uiPersist(()=>s.uiBatch={id:uid(),start:next,end:next+count-1,count,ending:$('#uEnding').value,options:$('#uBatchOptions').value,status:'preparing'});if(!lfPlans(s,next).some(p=>p.kind==='chapter')){await lfSend(s,'GENERATE_OUTLINE',{extendTo:next+count-1,preserveExisting:true});toast('Đã yêu cầu mở rộng dàn ý. Bạn duyệt kế hoạch mới trước khi viết.');return}const defaults=lfChapterDefaults(s),ending={continue:'Tiếp tục phát triển câu chuyện.',arc:'Phát triển sâu Arc hiện tại; chưa khép các nút thắt chính của Arc.',newarc:'Khép dần Arc hiện tại và mở một Arc mới có xung đột mới.',open:'Chuẩn bị kết mở, giải quyết xung đột trung tâm nhưng giữ khả năng tiếp nối.',closed:'Chuẩn bị kết đóng trọn vẹn, giải quyết các nút thắt bằng sự kiện thực sự.'}[s.uiBatch.ending]||'';defaults.prompt+='\n'+ending+'\n'+s.uiBatch.options;openEditor('content','',defaults);toast('Đã chuẩn bị đợt chương. Viết và duyệt từng chương để giữ đúng ngữ cảnh.')}
async function uiAddReference(p){uiFlushPrint();const d=await choose('Thêm mẫu tham khảo',input('title','Tên mẫu','','text','required')+input('link','Link tham khảo','','url')+'<p>Để thêm ảnh từ máy, chọn Nhập ảnh tham khảo ở bước sau.</p>'+select('mode','Cách thêm',[['link','Lưu link'],['image','Nhập ảnh tham khảo']],'link'));if(!d)return;if(d.mode==='image')return uiImportImage(p,'reference',d.title,d.link);if(!d.link)throw Error('Nhập link tham khảo.');if(!/^https?:\/\//i.test(d.link))throw Error('Link phải là http hoặc https.');uiPersist(()=>p.references.push({id:uid(),title:d.title,link:d.link,source:new URL(d.link).hostname}));}
